//! Stable publication with a manifest of precisely the files generation owns.
use std::collections::BTreeSet;
use std::fs;
use std::io;
use std::path::Path;

use crate::File;

const MARKER: &str = ".crucible";
const LEGACY: &str =
    "Generated by crucible. This directory is emptied and rewritten on every run.\n";

/// Publish generated files and remove only obsolete files from the previous
/// manifest. Handwritten files and native build/dependency directories survive.
/// Invalid paths, ownership collisions and symlinks are checked before writes.
pub fn write(out: &Path, files: &[File]) -> io::Result<()> {
    reject_symlinks(out)?;
    let marker = out.join(MARKER);
    reject_symlinks(&marker)?;
    let mut legacy = false;
    let previous: BTreeSet<String> = match fs::read_to_string(&marker) {
        Ok(text) if text == LEGACY => {
            // The old marker did not track paths. Adopt current generated files
            // but retain unknown old files rather than delete consumer content.
            legacy = true;
            BTreeSet::new()
        }
        Ok(text) => serde_json::from_str(&text).map_err(io::Error::other)?,
        Err(error) if error.kind() == io::ErrorKind::NotFound => BTreeSet::new(),
        Err(error) => return Err(error),
    };
    let mut current = BTreeSet::new();
    let mut portable_paths = BTreeSet::new();
    for file in files {
        validate(&file.path)?;
        if !portable_paths.insert(file.path.to_ascii_lowercase())
            || !current.insert(file.path.clone())
        {
            return Err(io::Error::other(format!(
                "duplicate generated path: {}",
                file.path
            )));
        }
    }
    for relative in previous.union(&current) {
        validate(relative)?;
        let path = out.join(relative);
        reject_symlinks(&path)?;
        if path.exists() && !path.is_file() {
            return Err(io::Error::other(format!(
                "generated path is not a file: {}",
                path.display()
            )));
        }
        if current.contains(relative)
            && path.exists()
            && !legacy
            && !previous_owns(out, relative, &previous)?
        {
            return Err(io::Error::other(format!(
                "{} holds a file crucible did not write; refusing to replace it",
                path.display()
            )));
        }
    }
    for relative in &current {
        let path = Path::new(relative);
        for ancestor in path.ancestors().skip(1) {
            if let Some(ancestor) = ancestor
                .to_str()
                .filter(|ancestor| portable_paths.contains(&ancestor.to_ascii_lowercase()))
            {
                return Err(io::Error::other(format!(
                    "generated file is also a parent directory: {ancestor}"
                )));
            }
        }
    }
    fs::create_dir_all(out)?;
    // An I/O error below must not strand files the old manifest doesn't list:
    // the next run would take them for consumer files and refuse forever. So
    // the manifest first claims the union of old and new paths.
    let union: BTreeSet<&String> = previous.union(&current).collect();
    write_changed(
        &marker,
        &serde_json::to_vec_pretty(&union).map_err(io::Error::other)?,
    )?;
    // Removed before writing: on a case-insensitive filesystem an obsolete
    // `Foo.txt` is the very file a new `foo.txt` is written to.
    for relative in previous.difference(&current) {
        let path = out.join(relative);
        match fs::remove_file(&path) {
            Ok(()) => {}
            Err(error) if error.kind() == io::ErrorKind::NotFound => {}
            Err(error) => return Err(error),
        }
    }
    for file in files {
        let path = out.join(&file.path);
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        write_changed(&path, file.contents.as_bytes())?;
    }
    write_changed(
        &marker,
        &serde_json::to_vec_pretty(&current).map_err(io::Error::other)?,
    )
}

/// Whether the file already at `out/relative` is one the previous manifest
/// lists. Names are compared exactly, except that a case-insensitive
/// filesystem resolves `foo.txt` to an existing `Foo.txt`: that file is owned
/// only if its on-disk name is listed. Unclear resolution is not ownership.
fn previous_owns(out: &Path, relative: &str, previous: &BTreeSet<String>) -> io::Result<bool> {
    if previous.contains(relative) {
        return Ok(true);
    }
    let mut dir = out.to_path_buf();
    let mut resolved = Vec::new();
    for segment in relative.split('/') {
        let mut matches = Vec::new();
        for entry in fs::read_dir(&dir)? {
            let name = entry?.file_name();
            let Some(name) = name.to_str() else { continue };
            if name == segment {
                matches = vec![name.to_owned()];
                break;
            }
            if name.eq_ignore_ascii_case(segment) {
                matches.push(name.to_owned());
            }
        }
        let [name] = matches.as_slice() else {
            return Ok(false);
        };
        dir.push(name);
        resolved.push(name.clone());
    }
    Ok(previous.contains(&resolved.join("/")))
}

fn validate(relative: &str) -> io::Result<()> {
    let mut segments = relative.split('/');
    let first = segments.next().unwrap_or_default().to_ascii_lowercase();
    if relative.contains(['\\', ':'])
        || relative.chars().any(char::is_control)
        || relative
            .split('/')
            .any(|part| matches!(part, "" | "." | "..") || part.ends_with(['.', ' ']))
        || matches!(
            first.as_str(),
            MARKER | ".git" | "node_modules" | "dist" | "target" | ".build"
        )
    {
        return Err(io::Error::other(format!(
            "unsafe generated path: {relative:?}"
        )));
    }
    Ok(())
}

fn reject_symlinks(path: &Path) -> io::Result<()> {
    for ancestor in path.ancestors() {
        match fs::symlink_metadata(ancestor) {
            Ok(metadata) if metadata.file_type().is_symlink() => {
                return Err(io::Error::other(format!(
                    "refusing generated output through symlink: {}",
                    ancestor.display()
                )));
            }
            Ok(_) => {}
            Err(error) if error.kind() == io::ErrorKind::NotFound => {}
            Err(error) => return Err(error),
        }
    }
    Ok(())
}

fn write_changed(path: &Path, contents: &[u8]) -> io::Result<()> {
    match fs::read(path) {
        Ok(existing) if existing == contents => Ok(()),
        Ok(_) => fs::write(path, contents),
        Err(error) if error.kind() == io::ErrorKind::NotFound => fs::write(path, contents),
        Err(error) => Err(error),
    }
}
